const updateBackupPlan = `-- name: UpdateBackupPlan :one
UPDATE database_backup_plans SET
    name = $1, folder = $2, selection = $3, targets = $4::text[],
    pattern = $5, method = $6, full_every_days = $7,
    retention = $8, keep_days = $9, gfs_daily = $10,
    gfs_weekly = $11, gfs_monthly = $12,
    runner_server_id = $13, username = $14,
    password_enc = $15, cron = $16, timezone = $17,
    enabled = $18, next_run_at = $19,
    updated_by = $20, updated_at = now()
WHERE id = $21
RETURNING id, workspace_id, database_id, name, folder, runner_server_id, username, password_enc, cron, timezone, enabled, next_run_at, created_by, updated_by, created_at, updated_at, selection, targets, pattern, method, full_every_days, retention, keep_days, gfs_daily, gfs_weekly, gfs_monthly
`

type UpdateBackupPlanParams struct {
	Name           string     `json:"name"`
	Folder         string     `json:"folder"`
	Selection      string     `json:"selection"`
	Targets        []string   `json:"targets"`
	Pattern        string     `json:"pattern"`
	Method         string     `json:"method"`
	FullEveryDays  int32      `json:"full_every_days"`
	Retention      string     `json:"retention"`
	KeepDays       int32      `json:"keep_days"`
	GfsDaily       int32      `json:"gfs_daily"`
	GfsWeekly      int32      `json:"gfs_weekly"`
	GfsMonthly     int32      `json:"gfs_monthly"`
	RunnerServerID *uuid.UUID `json:"runner_server_id"`
	Username       string     `json:"username"`
	PasswordEnc    []byte     `json:"password_enc"`
	Cron           string     `json:"cron"`
	Timezone       string     `json:"timezone"`
	Enabled        bool       `json:"enabled"`
	NextRunAt      *time.Time `json:"next_run_at"`
	UpdatedBy      *uuid.UUID `json:"updated_by"`
	ID             uuid.UUID  `json:"id"`
}

func (q *Queries) UpdateBackupPlan(ctx context.Context, arg UpdateBackupPlanParams) (DatabaseBackupPlan, error) {
	row := q.db.QueryRow(ctx, updateBackupPlan,
		arg.Name,
		arg.Folder,
		arg.Selection,
		arg.Targets,
		arg.Pattern,
		arg.Method,
		arg.FullEveryDays,
		arg.Retention,
		arg.KeepDays,
		arg.GfsDaily,
		arg.GfsWeekly,
		arg.GfsMonthly,
		arg.RunnerServerID,
		arg.Username,
		arg.PasswordEnc,
		arg.Cron,
		arg.Timezone,
		arg.Enabled,
		arg.NextRunAt,
		arg.UpdatedBy,
		arg.ID,
	)
	var i DatabaseBackupPlan
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.DatabaseID,
		&i.Name,
		&i.Folder,
		&i.RunnerServerID,
		&i.Username,
		&i.PasswordEnc,
		&i.Cron,
		&i.Timezone,
		&i.Enabled,
		&i.NextRunAt,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Selection,
		&i.Targets,
		&i.Pattern,
		&i.Method,
		&i.FullEveryDays,
		&i.Retention,
		&i.KeepDays,
		&i.GfsDaily,
		&i.GfsWeekly,
		&i.GfsMonthly,
	)
	return i, err
}
